def valid_given(name,args):
    if type(args) is not list: return False
    if name=='s151_b': return len(args)==3 and type(args[0]) is str and type(args[1]) in (int,float) and type(args[2]) is int
    if name=='s63_f_1_A': return len(args)==2 and type(args[0]) is str and type(args[1]) is int
    if name in ('s151_b_applies','s151_c_applies','s152_c_1','s63_f_1_B'):
        return len(args)==3 and type(args[0]) is str and type(args[1]) is str and type(args[2]) is int
    return False


def timed(facts,event,record,reasons,label,allow_onset):
    form=record.get('form'); start=record.get('start_date'); end=record.get('end_date'); date=record.get('as_of_date')
    if form=='ongoing_since' and type(start) is str:
        put(facts,'start_',[event,start]); return True
    if form=='closed_interval' and type(start) is str and type(end) is str:
        put(facts,'start_',[event,start]); put(facts,'end_',[event,end]); return True
    if form=='active_on_date' and type(date) is str:
        put(facts,'start_',[event,date]); put(facts,'end_',[event,date]); return True
    if form=='onset_only' and allow_onset and type(start) is str:
        put(facts,'start_',[event,start]); return True
    if form=='onset_only': add(reasons,label+'_onset_does_not_establish_later_persistence')
    else: add(reasons,label+'_time_invalid')
    return False


